<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'proposals']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">COMERCIAL</p><h2>Propostas</h2><p>Solicitações recebidas pelo formulário público de contato.</p></div></header><form class="studio-filter-bar studio-single-filter" method="get"><label><span>Status</span><select name="status"><option value="">Todos</option><?php foreach(['new','contacted','qualified','won','lost','archived'] as $value):?><option value="<?= $value ?>"<?= $status===$value?' selected':'' ?>><?= $value ?></option><?php endforeach;?></select></label><button>Filtrar</button></form><div class="studio-table-wrap"><table><thead><tr><th>Contato</th><th>Serviço</th><th>Mensagem</th><th>Status</th></tr></thead><tbody><?php if($records===[]):?><tr><td colspan="4" class="studio-empty">Nenhuma proposta recebida.</td></tr><?php endif;?><?php foreach($records as $record):?><tr><td><strong><?= $this->e($record['name']) ?></strong><br><?= $this->e($record['email']) ?></td><td><?= $this->e($record['service']) ?></td><td><?= $this->e($record['message']) ?></td><td><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= $this->e((string)$record['id']) ?>"><select name="status" onchange="this.form.submit()"><?php foreach(['new','contacted','qualified','won','lost','archived'] as $value):?><option value="<?= $value ?>"<?= $record['status']===$value?' selected':'' ?>><?= $value ?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div></section>
